begin;
create temporary table feature_fixture(owner_id uuid,member_id uuid,outsider_id uuid,community_id uuid,channel_id uuid,second_channel uuid,message_id uuid) on commit drop;
insert into feature_fixture values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
grant select,update on feature_fixture to authenticated;
insert into auth.users(id,aud,role,email,raw_user_meta_data,raw_app_meta_data,created_at,updated_at)
select uid,'authenticated','authenticated','qa-'||uid||'@example.invalid',jsonb_build_object('display_name','QA temporário'),'{"provider":"email","providers":["email"]}'::jsonb,now(),now()
from feature_fixture f cross join lateral unnest(array[f.owner_id,f.member_id,f.outsider_id])uid;
insert into public.communities(id,name,created_by,invite_only)select community_id,'QA temporária',owner_id,true from feature_fixture;
insert into public.community_members(community_id,user_id)select community_id,member_id from feature_fixture;
insert into public.channels(id,name,kind,community_id,created_by)select channel_id,'qa','text',community_id,owner_id from feature_fixture union all select second_channel,'qa-dois','text',community_id,owner_id from feature_fixture;
update orbita_private.push_config set transport_hash=encode(sha256(convert_to('qa-temp-secret','UTF8')),'hex');
insert into public.push_subscriptions(user_id,endpoint,p256dh,auth)select member_id,'https://fcm.googleapis.com/fcm/send/qa-'||member_id,repeat('A',87),repeat('A',22) from feature_fixture;
set local role authenticated;
do $$declare f record;denied boolean; original_count integer;friend_id uuid;conversation uuid;direct_root uuid;affected integer;voice uuid:=gen_random_uuid();snapshot jsonb;begin
 select * into f from feature_fixture;
 perform set_config('request.jwt.claim.sub',f.owner_id::text,true);
 if not orbita_private.can_read_channel(f.channel_id) then raise exception 'FAIL owner access';end if;
 insert into public.messages(channel_id,author_id,content)values(f.channel_id,f.owner_id,'azulejo auditável @'||(select username from public.profiles where id=f.member_id)) returning id into f.message_id;
 update feature_fixture set message_id=f.message_id;
 if jsonb_array_length(public.push_take('qa-temp-secret'))<>1 then raise exception 'FAIL push queue delivery';end if;
 for affected in 1..8 loop insert into public.messages(channel_id,author_id,content)values(f.channel_id,f.owner_id,'fila @'||(select username from public.profiles where id=f.member_id));end loop;
 if jsonb_array_length(public.push_take('qa-temp-secret'))<>5 then raise exception 'FAIL bounded push batch';end if;
 if jsonb_array_length(public.push_take('qa-temp-secret'))<>3 then raise exception 'FAIL push lease isolation';end if;
 if not exists(select 1 from public.messages where id=f.message_id and search_vector@@plainto_tsquery('portuguese','azulejo'))then raise exception 'FAIL indexed search';end if;
 update public.messages set content='azulejo editado' where id=f.message_id;
 if not exists(select 1 from public.messages where id=f.message_id and edited_at is not null)then raise exception 'FAIL edit timestamp';end if;
 denied:=false;begin update public.messages set channel_id=f.second_channel where id=f.message_id;exception when others then denied:=true;end;if not denied then raise exception 'FAIL immutable scope';end if;
 denied:=false;begin insert into public.messages(channel_id,author_id,content,thread_root)values(f.second_channel,f.owner_id,'thread incorreta',f.message_id);exception when others then denied:=true;end;if not denied then raise exception 'FAIL cross-scope thread';end if;
 perform set_config('request.jwt.claim.sub',f.member_id::text,true);
 insert into public.messages(channel_id,author_id,content,thread_root)values(f.channel_id,f.member_id,'resposta correta',f.message_id);
 perform set_config('request.jwt.claim.sub',f.owner_id::text,true);
 insert into public.friendships(requester_id,recipient_id)values(f.owner_id,f.member_id)returning id into friend_id;
 perform set_config('request.jwt.claim.sub',f.member_id::text,true);
 update public.friendships set status='accepted' where id=friend_id;
 perform set_config('request.jwt.claim.sub',f.owner_id::text,true);
 insert into public.conversations(user_a,user_b)values(least(f.owner_id,f.member_id),greatest(f.owner_id,f.member_id))returning id into conversation;
 insert into public.direct_messages(conversation_id,author_id,content)values(conversation,f.owner_id,'DM temporária')returning id into direct_root;
 perform set_config('request.jwt.claim.sub',f.member_id::text,true);
 insert into public.direct_messages(conversation_id,author_id,content,thread_root)values(conversation,f.member_id,'resposta privada',direct_root);
 update public.direct_messages set content='edição indevida' where id=direct_root;get diagnostics affected=row_count;if affected<>0 then raise exception 'FAIL editing another DM author';end if;
 perform set_config('request.jwt.claim.sub',f.outsider_id::text,true);
 if exists(select 1 from public.direct_messages where conversation_id=conversation)then raise exception 'FAIL private conversation RLS';end if;
 perform set_config('request.jwt.claim.sub',f.member_id::text,true);
 denied:=false;begin perform public.moderate_member(f.community_id,f.owner_id,'ban');exception when others then denied:=true;end;if not denied then raise exception 'FAIL unauthorized moderation';end if;
 denied:=false;begin perform public.push_take('not-the-server-secret');exception when others then denied:=true;end;if not denied then raise exception 'FAIL push queue exposed';end if;
 perform set_config('request.jwt.claim.sub',f.outsider_id::text,true);
 if orbita_private.can_read_channel(f.channel_id) then raise exception 'FAIL outsider access';end if;
 if exists(select 1 from public.messages where id=f.message_id)then raise exception 'FAIL outsider RLS';end if;
 perform set_config('request.jwt.claim.sub',f.owner_id::text,true);
 insert into public.channels(name,kind,community_id,is_private,is_stage)values('qa-voice','voice',f.community_id,true,true);
 select id into voice from public.channels where community_id=f.community_id and name='qa-voice';
 if voice is null then raise exception 'FAIL new voice channel visibility';end if;
 insert into public.channel_members(channel_id,user_id,added_by)values(voice,f.member_id,f.owner_id);
 snapshot:=public.voice_access_snapshot(voice,array[f.owner_id,f.member_id,f.outsider_id]);
 if not (snapshot->'participants' ? f.member_id::text) or (snapshot->'participants' ? f.outsider_id::text) or (snapshot->'participants'->>f.member_id::text)::boolean then raise exception 'FAIL private stage access';end if;
 perform public.voice_authorize(voice,f.member_id,'speaker');
 if not (public.voice_access_snapshot(voice,array[f.member_id])->'participants'->>f.member_id::text)::boolean then raise exception 'FAIL stage speaker permission';end if;
 delete from public.channel_members where channel_id=voice and user_id=f.member_id;
 if public.voice_access_snapshot(voice,array[f.member_id])->'participants' ? f.member_id::text then raise exception 'FAIL revoked voice access';end if;
 insert into public.channel_members(channel_id,user_id,added_by)values(voice,f.member_id,f.owner_id);
 perform set_config('request.jwt.claim.sub',f.member_id::text,true);
 denied:=false;begin perform public.voice_access_snapshot(voice,array[f.owner_id]);exception when others then denied:=true;end;if not denied then raise exception 'FAIL unauthorized voice snapshot';end if;
 perform set_config('request.jwt.claim.sub',f.owner_id::text,true);
 perform public.moderate_member(f.community_id,f.member_id,'timeout','QA',10);
 if (public.voice_access_snapshot(voice,array[f.member_id])->'participants'->>f.member_id::text)::boolean then raise exception 'FAIL voice timeout';end if;
 perform set_config('request.jwt.claim.sub',f.member_id::text,true);
 denied:=false;begin insert into public.messages(channel_id,author_id,content)values(f.channel_id,f.member_id,'não pode enviar');exception when others then denied:=true;end;if not denied then raise exception 'FAIL timeout posting';end if;
 denied:=false;begin insert into public.reactions(message_id,user_id,emoji)values(f.message_id,f.member_id,'👍');exception when others then denied:=true;end;if not denied then raise exception 'FAIL timeout reacting';end if;
 perform set_config('request.jwt.claim.sub',f.owner_id::text,true);
 perform public.moderate_member(f.community_id,f.member_id,'ban','QA',10);
 if (select count(*) from public.audit_log where community_id=f.community_id)<>3 then raise exception 'FAIL audit';end if;
 perform set_config('request.jwt.claim.sub',f.member_id::text,true);
 if orbita_private.can_read_channel(f.channel_id)then raise exception 'FAIL ban access';end if;
 if exists(select 1 from public.messages where id=f.message_id)then raise exception 'FAIL banned RLS';end if;
 perform set_config('request.jwt.claim.sub',f.owner_id::text,true);
 denied:=false;begin perform public.moderate_member(f.community_id,f.owner_id,'ban');exception when others then denied:=true;end;if not denied then raise exception 'FAIL self moderation';end if;
end$$;
rollback;
select 'permission, search, threads, timeout, ban and audit checks passed; all fixtures rolled back' as validation;
